"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[9095],{89095:a=>{a.exports=JSON.parse('{"meta":{"title":"Aplikasi Waktu Solat Salat-e-Mustaqeem untuk iPhone dan Android - iMuslim Life","description":"Salat-e-Mustaqeem 1.09.1 untuk iPhone, Android, Apple Watch dan Galaxy Watch: Mushaf berhias, Al-Quran selepas Solat, Azan penuh, Journey untuk keluarga, widget dan Siri. Percuma dan tanpa iklan."},"store":{"appleSmall":"Muat turun di","appleBig":"App Store","playSmall":"Dapatkan di","playBig":"Google Play"},"hero":{"iconAlt":"Ikon aplikasi Salat-e-Mustaqeem","lede":"Waktu solat, Al-Quran perkataan demi perkataan, dan skrin utama tenang yang mengikut langit. Di iPhone, telefon Android, Apple Watch dan Alexa.","facts":"Percuma \xb7 Tanpa iklan \xb7 Berfungsi luar talian \xb7 English, \u0627\u0644\u0639\u0631\u0628\u064a\u0629, \u0627\u0631\u062f\u0648","alts":["Helaian perkataan dalam pembaca Al-Quran","Tab solat berbentuk jam matahari","Skrin utama N\u016br dengan kiraan detik solat seterusnya"]},"whatsNew":{"eyebrow":"Baharu dalam {{v}}","h2":"Al-Quran, bercahaya","lede":"Mushaf untuk dibaca, dipelajari dan dihafaz, serta sedikit Al-Quran selepas setiap solat.","items":[{"title":"Mushaf berhias","text":"Baca pada halaman Mushaf dengan garis hasyiah, tanda rukuk, rubuk hizb, manzil dan sajdah, serta kata pembuka setiap juzuk berwarna emas."},{"title":"Baca, Perkataan dan Mushaf","text":"Tiga cara ke halaman yang sama: teks mengalir, setiap perkataan dengan maknanya, atau Mushaf bercetak. Ketik mana-mana perkataan untuk melihat makna dan tajwidnya."},{"title":"Al-Quran selepas Solat","text":"Khatamkan Al-Quran sedikit demi sedikit selepas setiap solat, dalam 7, 15, 30 atau 60 hari."},{"title":"Al-Quranku dan Info Surah","text":"Penanda, nota dan koleksi di satu tempat, serta pengenalan setiap surah daripada Tafsir Ibn Kathir."},{"title":"Ayat dan Doa Hari Ini","text":"Ayat yang sama untuk seluruh Ummah setiap hari, kini juga di skrin utama dan skrin kunci, luar talian selama seminggu."},{"title":"Radio Al-Quran dan Kongsi ayat","text":"Bacaan berterusan daripada qari kegemaran anda, dan mana-mana ayat dikongsi sebagai imej yang indah."}]},"quran":{"eyebrow":"Al-Quran, perkataan demi perkataan","h2":"Fahami setiap perkataan yang anda baca","lede":"Ketik mana-mana perkataan untuk melihat maknanya, cara menyebutnya dan hukum tajwid yang terpakai. Dengar setiap ayat menyala, dan sambung tepat di tempat anda berhenti.","bullets":[{"b":"77,429 perkataan","t":"dengan makna bahasa Inggeris dan Urdu serta transliterasi."},{"b":"Dengar satu perkataan sahaja,","t":"dipotong daripada bacaan, walaupun luar talian."},{"b":"Surah penuh luar talian,","t":"dimuat turun atau disimpan semasa mendengar, dalam Muat turun & storan."},{"b":"Mendengar di latar belakang","t":"dengan kawalan Skrin Kunci, kelajuan dan pemasa tidur."},{"b":"Lebih 30 qari,","t":"termasuk Maher Al-Muaiqly, Husary, Abdul Basit dan al-Tablawi."},{"b":"Sambung membaca","t":"pada ayat yang tepat, dan lompat ke mana-mana surah atau juzuk dengan namanya."}],"alts":["Susun atur Perkataan, dengan makna di bawah setiap perkataan","Helaian untuk satu perkataan","Bacaan berpandu dalam Surah Yasin"]},"prayer":{"eyebrow":"Solat, sepanjang hari","h2":"Jangan terlepas solat","lede":"Hari anda sebagai jam matahari, skrin utama yang mengikut langit, dan peringatan yang tiba tepat pada waktunya, dengan azan penuh daripada muazin pilihan anda.","bullets":[{"b":"Peringatan azan penuh","t":"daripada tujuh muazin, dengan azan khas Subuh."},{"b":"Laluan solat hari ini:","t":"ketik solat setelah anda menunaikannya, atau tambahkan ke qada."},{"b":"Azan penuh di iPhone,","t":"melepasi had 30 saat, pada iOS 26 (Eksperimen)."},{"b":"Waktu anda sendiri:","t":"laraskan mana-mana solat dan tambah peringatan sebelum azan."},{"b":"Enam tema skrin utama","t":"dan mod gelap penuh, lembut di mata waktu Subuh."},{"b":"Sedia untuk musafir:","t":"waktu solat mengikut anda ke bandar baharu, dan berfungsi tanpa sambungan."},{"b":"Kompas kiblat","t":"yang memberitahu ke arah mana untuk berpaling."}],"alts":["Tab solat berbentuk jam matahari","Skrin utama N\u016br","Skrin utama N\u016br dalam mod gelap"]},"shots":{"eyebrow":"Versi {{v}}","h2":"Tangkapan Skrin Aplikasi","lede":"Leret untuk melihat Salat-e-Mustaqeem yang baharu.","label":"Tangkapan skrin aplikasi","prev":"Tangkapan skrin sebelumnya","next":"Tangkapan skrin seterusnya","alts":["Skrin utama dengan solat seterusnya dan laluan solat hari ini","Jam matahari: semua waktu solat pada satu gelang","Surah Yasin dalam susun atur Perkataan","Helaian perkataan: makna, bunyi dan tajwid satu perkataan","Doa dikumpulkan mengikut waktu","Pembilang zikir selepas setiap solat","Kalkulator zakat dengan nisab hari ini","Kompas kiblat dan jarak ke Makkah","Skrin utama dalam mod gelap","Pembaca Al-Quran dalam mod gelap"]},"watch":{"eyebrow":"Baharu \xb7 Apple Watch","h2":"Waktu solat di pergelangan tangan","lede":"Solat seterusnya di muka jam, langit hari ini sebagai jam matahari, pencari kiblat dan tasbih yang dikira dengan Digital Crown. Disertakan dengan aplikasi iPhone.","alt":"Apple Watch: {{title}}","items":[{"title":"Komplikasi","text":"Solat seterusnya di muka jam"},{"title":"Hari ini","text":"Jam matahari dengan langit yang hidup"},{"title":"Waktu","text":"Kelima-lima solat sekali pandang"},{"title":"Kiblat","text":"Pusing hingga terkunci, dengan ketukan lembut"},{"title":"Tasbih","text":"33 biji dengan crown atau ketikan"}]},"everywhere":{"eyebrow":"Di mana jua anda berada","h2":"Zikir, ke mana pun anda memandang","siriH":"Tanya sahaja Siri","siriSub":"Tanpa tetapan, dalam bahasa Inggeris dan Arab:","cards":[{"title":"Kiraan detik di Skrin Kunci","text":"Kiraan detik solat di Skrin Kunci dan Dynamic Island. Ketik \u201cSaya sudah solat\u201d untuk merekod solat anda."},{"title":"Widget skrin utama","text":"Widget zamrud dan emas di iPhone dan Android, kini memaparkan bandar anda."},{"title":"Alexa: Muslim Companion","text":"Echo anda melaungkan azan setiap waktu solat, membacakan mana-mana surah dan membimbing hafazan anda."}],"alexaLink":"Terokai skill Alexa \u2192","phrases":["When is the next prayer in Salat-e-Mustaqeem","When is Asr in Salat-e-Mustaqeem","Today\u2019s prayer times in Salat-e-Mustaqeem","Where is the Qibla in Salat-e-Mustaqeem","What\u2019s the Islamic date in Salat-e-Mustaqeem","When is iftar in Salat-e-Mustaqeem"]},"features":{"eyebrow":"Semua di dalamnya","h2":"Satu aplikasi untuk hari ibadah anda","items":[{"title":"Peringatan azan","text":"Azan, bip atau senyap bagi setiap solat."},{"title":"Kiblat","text":"Kompas yang menghalakan anda ke Kaabah."},{"title":"Tafsir","text":"Tafsir yang jelas dan mudah dibaca bagi setiap ayat."},{"title":"Mod gelap","text":"Sepuluh warna aksen, enam tema skrin utama."},{"title":"Tiga bahasa","text":"Inggeris, Arab dan Urdu."},{"title":"Berfungsi luar talian","text":"Waktu solat dan Al-Quran tanpa sambungan."}]},"faq":{"eyebrow":"Soalan","h2":"Soalan lazim","items":[{"q":"Sejauh mana tepatnya waktu solat?","a":"Waktu dikira untuk lokasi tepat anda. Pilih kaedah pengiraan dan mazhab Asar (Syafie atau Hanafi) yang diikuti masjid anda. Apabila bermusafir, waktu dan peringatan mengikut anda."},{"q":"Adakah aplikasi berfungsi luar talian?","a":"Ya. Tanpa sambungan, waktu solat dikira di telefon, dan teks Al-Quran, makna perkataan serta ayat yang telah anda dengar kekal tersedia luar talian."},{"q":"Adakah Salat-e-Mustaqeem percuma?","a":"Ya. Semua ciri percuma, tanpa iklan dan tanpa pembelian dalam aplikasi. Kami percaya alat bantu solat patut terbuka kepada semua."},{"q":"Peranti apa yang disokong?","a":"iPhone dan iPad dengan iOS 17 atau lebih baharu, Apple Watch dengan watchOS 11 atau lebih baharu (disertakan dengan aplikasi iPhone), telefon Android 7.0 atau lebih baharu, serta Galaxy Watch dan jam Wear OS lain (disertakan dengan aplikasi Android)."},{"q":"Bagaimana menambah widget?","a":"Di iPhone, sentuh dan tahan Skrin Utama, ketik Edit, kemudian Tambah Widget, dan cari Salat-e-Mustaqeem. Di Android, sentuh dan tahan skrin utama, ketik Widget dan pilih Salat-e-Mustaqeem. Pilih Solat Seterusnya, Solat Hari Ini atau Solat Semasa."},{"q":"Bahasa apa yang digunakan aplikasi?","a":"Aplikasi tersedia dalam bahasa Inggeris, Arab dan Urdu (Tetapan \u2192 Bahasa), dengan susun atur kanan ke kiri. Makna perkataan dalam bahasa Inggeris dan Urdu, dan Siri memahami bahasa Inggeris dan Arab."},{"q":"Adakah skill Alexa?","a":"Ya, Muslim Companion. Ia melaungkan azan di Echo anda setiap waktu solat, membacakan mana-mana surah, membimbing hafazan dan menemani anda pada bulan Ramadan. Sebut \u201cAlexa, open Muslim Companion\u201d."}],"idea":"Ada idea untuk versi seterusnya?","suggest":"Cadangkan ciri"},"download":{"h2":"Muat turun Salat-e-Mustaqeem","lede":"Percuma, tanpa iklan. Untuk iPhone, iPad, Apple Watch dan Android.","qr":["Imbas untuk App Store","Imbas untuk Google Play"],"ayah":"Tunjukilah kami jalan yang lurus. \u2014 Al-Fatihah 1:6"},"seal":{"label":"Versi {{v}}","word":"VERSI"},"releases":{"kicker":"Perjalanan 1.04 \u2192 {{v}}","h2":"Tujuh keluaran dalam tiga minggu","tabs":"Keluaran","items":[{"summary":"Azan penuh, aplikasi jam untuk Android, dan Al-Quran tanpa sambungan.","features":[{"tag":"iPhone \xb7 Eksperimen","title":"Azan penuh","text":"Pada iOS 26, azan penuh berkumandang setiap waktu solat, bukan klip 30 saat."},{"tag":"Wear OS","title":"Aplikasi Galaxy Watch","text":"Jubin dan komplikasi yang mengira detik ke solat seterusnya."},{"tag":"Al-Quran","title":"Surah luar talian","text":"Muat turun surah penuh, atau simpan yang anda mainkan. Uruskan dalam Muat turun & storan."},{"tag":"Al-Quran","title":"Qari dan terjemahan dalam pemain","text":"Pilih daripada 33 qari dan dengar terjemahan bersama setiap surah."}],"more":"Juga dalam 1.04: kiraan detik di skrin kunci sebelum setiap solat di Android, pintasan aplikasi, peringatan yang direka semula, panduan solat beranimasi, dan aplikasi di Mac."},{"summary":"Kisah setiap minggu, dan cara yang lebih tenang untuk belajar doa.","features":[{"tag":"Belajar","title":"Kisah mingguan","text":"Kisah baharu setiap minggu daripada Sirah, para Nabi dan para Sahabat, dalam bahasa Inggeris dan Urdu."},{"tag":"Al-Quran","title":"Tukar qari di tengah surah","text":"Tukar suara tanpa kehilangan tempat bacaan."},{"tag":"Doa","title":"Doa yang direka semula","text":"Doa dikumpulkan mengikut waktu, dengan langkah doa ditambah ke panduan solat."},{"tag":"Alexa","title":"Echo anda, dari aplikasi","text":"Sediakan Muslim Companion dan azannya dari telefon anda."}],"more":"Juga dalam 1.05: grafik Aktiviti Langsung yang terisi apabila waktu solat hampir, dan panduan widget Android."},{"summary":"Journey: cara lembut untuk seluruh keluarga berkembang dalam solat, bersama-sama.","features":[{"tag":"Keluarga","title":"Journey","text":"Tandakan solat, masa Al-Quran dan zikir sebagai keluarga, dan lihat pelita anda menyala."},{"tag":"Kanak-kanak","title":"Rihla dan Masjidku","text":"Kanak-kanak menjelajah peta bandar-bandar Islam dan membina masjid sendiri sambil mereka solat."},{"tag":"Keluarga","title":"Kuiz dan malam kuiz","text":"Kuiz Islam harian, dan malam kuiz bersama melalui SharePlay."},{"tag":"Solat","title":"Waktu solat anda sendiri","text":"Laraskan mana-mana solat mengikut minit, tambah peringatan sebelum azan, dan perhalusi tarikh Hijrah."}],"more":"Juga dalam 1.06: musim dan episod dalam Journey, widget Pelita, nisab zakat, serta Perihal & penghargaan."},{"summary":"Penambahbaikan dan pembetulan, dengan kad Niyyah dalam perjalanan.","features":[{"tag":"Utama","title":"Kad Niyyah","text":"Niat ringkas di skrin utama untuk memulakan hari dengan tujuan."}],"more":""},{"summary":"Kalendar Islam baharu, mod Perjalanan dan Kiblat melalui kamera.","features":[{"tag":"Kalendar","title":"Kalendar Islam","text":"Bulan demi bulan, kad acara dan peringatan, Tambah ke Kalendar, dan widget kalendar."},{"tag":"Solat","title":"Mod Perjalanan","text":"Memaklumkan apabila anda bermusafir dan menawarkan solat qasar dan jamak."},{"tag":"Kiblat","title":"Kiblat dengan kamera","text":"Angkat telefon anda dan lihat arah Kiblat di bilik sekeliling anda."},{"tag":"iPhone \xb7 Android","title":"Sudah solat, di mana-mana","text":"Tandakan solat dari Skrin Kunci, Pusat Kawalan, StandBy atau peringatan itu sendiri."}],"more":"Juga dalam 1.08: Fokus Solat dan tindakan Pintasan, jubin Tetapan Pantas di Android, minit mindful dalam Apple Health dan Health Connect, serta lukisan pada setiap peringatan solat."},{"summary":"Al-Quran, bercahaya: Mushaf untuk dibaca, dipelajari dan dihafaz.","features":[{"tag":"Al-Quran","title":"Mushaf berhias","text":"Halaman Mushaf dengan garis hasyiah; ketik mana-mana perkataan untuk maknanya dan hafaz dari halaman."},{"tag":"Al-Quran","title":"Al-Quran selepas Solat","text":"Khatamkan Al-Quran sedikit demi sedikit selepas setiap solat, dalam 7, 15, 30 atau 60 hari."},{"tag":"Kajian","title":"Al-Quranku dan Info Surah","text":"Penanda, nota dan koleksi, serta pengenalan setiap surah daripada Tafsir Ibn Kathir."},{"tag":"Al-Quran","title":"Radio Al-Quran","text":"Bacaan berterusan daripada qari kegemaran anda."}],"more":"Juga dalam 1.09: kongsi mana-mana ayat sebagai imej, Ayat Hari Ini yang baharu untuk seluruh Ummah, sandaran dan penyegerakan tetapan dengan akaun anda, serta wajah jam dan widget Prayer Face baharu."},{"summary":"Widget baharu, dan kata pembuka setiap juzuk berwarna emas.","features":[{"tag":"Widget","title":"Ayat dan Doa Hari Ini","text":"Di skrin utama dan skrin kunci, iPhone dan Android, luar talian selama seminggu."},{"tag":"Android","title":"Widget Prayer Face","text":"Wajah tab Solat di skrin utama anda dalam tiga saiz, dengan pemilih wajah."},{"tag":"Al-Quran","title":"Pembuka juzuk berhias","text":"Perkataan yang menjadi nama setiap juzuk bersinar dalam Baca, Perkataan dan Mushaf."},{"tag":"Al-Quran","title":"Main dari ayat yang dipilih","text":"Ayat yang dipilih kini dimainkan dari ayat itu, bukan dari awal surah."}],"more":"Juga dalam 1.09.1: tanda Mushaf untuk rukuk, rubuk hizb, manzil dan sajdah; suku juzuk diberi nama; serta mikrofon dan lokasi adalah pilihan, jadi Android TV, kereta dan tablet masih boleh menggunakan apl."}]},"coming":{"badge":"Akan datang","eyebrow":"Dalam perjalanan","h2":"Akan datang","lede":"Sudah dibina, dan sedang diuji sebelum sampai ke telefon anda.","items":[{"title":"Tasm\u012b\u2018","text":"Bacalah dengan kuat dan lihat perkataan mana yang betul, dengan huruf Qaedah untuk pemula."},{"title":"Jurulatih Hifz","text":"Hafaz satu halaman demi satu halaman, dengan tajwid berwarna."}]}}')}}]);